// transactionalOffsets t txid g offset = true end for all

func lawspecCheckBrokerOffsetsSentInATransactionAre(symbols map[string]*lawSpecSymbol, caseContext string, t_ LawSpecValue, txid LawSpecValue, g LawSpecValue, offset LawSpecValue, withCluster LawSpecValue) {
	if lsTruth(lawSpecEvaluateCreated(symbols, t_, lsConvert("Int32", lsInteger("Int32", "1"), lawspecMachineBits))) {
		lsAssert(lsSourceContext(caseContext, "../src/contract.lawspec:206"), func() LawSpecValue {
			return lawSpecEvaluateTransactionalOffsets(symbols, t_, txid, g, offset)
		}, func() LawSpecValue {
			return lsBool(true)
		})
	}
}

var lawspecBrokerOffsetsSentInATransactionAreInputs = []string{"(text)", "(text)", "(text)", "(int Int64 0 9223372036854775807)"}

func lawspecBrokerOffsetsSentInATransactionAreCase(values []LawSpecValue) (float64, bool) {
	symbols := map[string]*lawSpecSymbol{}
	t_ := lsConvert("Text", values[0], lawspecMachineBits)
	txid := lsConvert("Text", values[1], lawspecMachineBits)
	g := lsConvert("Text", values[2], lawspecMachineBits)
	offset := lsConvert("Int64", values[3], lawspecMachineBits)
	if !(lsTruth(lawSpecEvaluateLawtwinKafkaModelValidTopicName(symbols, t_)) && lsTruth(lsBinary("!=", txid, lsText(""))) && lsTruth(lsBinary("!=", g, lsText(""))) && lsTruth(lsBinary(">=", offset, lsInteger("Integer", "0")))) {
		return 0, false
	}
	withCluster := lawspecConnectCluster(symbols, lsConvert("Unit", lsAbsent("Unit"), lawspecMachineBits))
	defer func() {
		_ = lawspecDisconnectCluster(symbols, withCluster)
	}()
	lsInstallHandlers(symbols, map[string]any{"lawtwin.kafka::ability::Broker": NewBrokerHandler(lsHandleCodec[any](_lawspecSchema, lawspecMachineBits, "lawtwin.kafka::type::Cluster", symbols).toNative(withCluster))})
	lawspecCheckBrokerOffsetsSentInATransactionAre(symbols, "lawtwin.kafka::Broker: |offsets sent in a transaction are committed only with it| [native] search", t_, txid, g, offset, withCluster)
	return 0, true
}

