// Admin: |a new topic has the partitions asked for| [native] — ../src/contract.lawspec:968
// for all (t :: Text) (n :: Int32) => match (attempt (createTopic t n)) { Either::Left
// railwayError0 -> false; Either::Right railwayValue1 -> true } implies partitionsFor t =
// Maybe::Present(n) end for all

func lawspecCheckAdminANewTopicHasThePartitionsAskedFor(symbols map[string]*lawSpecSymbol, caseContext string, t_ LawSpecValue, n LawSpecValue, withCluster LawSpecValue) {
	if lsTruth(lsMatchEither(lsAttempt("lawspec::ability::Fail(lawtwin.kafka.model::type::KafkaError)", func() LawSpecValue {
		return lsNativeFailures("lawspec::ability::Fail(lawtwin.kafka.model::type::KafkaError)", func(native any) LawSpecValue {
			return lawSpecKafkaErrorCodec(_lawspecSchema, lawspecMachineBits, symbols).fromNative(native.(KafkaError))
		}, func() LawSpecValue {
			return func() LawSpecValue {
				lsHandler(symbols, "lawtwin.kafka::ability::Admin").(Admin).CreateTopic(lsToNative("Text", t_, lawspecMachineBits).(string), lsToNative("Int32", n, lawspecMachineBits).(int32))
				return lsAbsent("Unit")
			}()
		})
	}, func(_value LawSpecValue) LawSpecValue {
		return _lawspecSchema.construct(lsNamed("Either", lsNamed("lawtwin.kafka.model::type::KafkaError"), lsNamed("Unit")), "Either::Right", []LawSpecValue{
			lsConvert("Unit", _value, lawspecMachineBits),
		}, lawspecMachineBits, symbols)
	}, func(_value LawSpecValue) LawSpecValue {
		return _lawspecSchema.construct(lsNamed("Either", lsNamed("lawtwin.kafka.model::type::KafkaError"), lsNamed("Unit")), "Either::Left", []LawSpecValue{
			_lawspecSchema.validate(lsNamed("lawtwin.kafka.model::type::KafkaError"), _value, lawspecMachineBits, symbols),
		}, lawspecMachineBits, symbols)
	}), func(railwayError0 LawSpecValue) LawSpecValue {
		return lsBool(false)
	}, func(railwayValue1 LawSpecValue) LawSpecValue {
		return lsBool(true)
	})) {
		_lawspecDataAssert(lsSourceContext(caseContext, "../src/contract.lawspec:973"), lsNamed("Maybe", lsNamed("Int32")), symbols, func() LawSpecValue {
			return lsMaybeCodec(_lawspecSchema, lawspecMachineBits, lsScalarCodec[int32](_lawspecSchema, lawspecMachineBits, "Int32"), symbols).fromNative(lsHandler(symbols, "lawtwin.kafka::ability::Admin").(Admin).PartitionsFor(lsToNative("Text", t_, lawspecMachineBits).(string)))
		}, func() LawSpecValue {
			return _lawspecSchema.construct(lsNamed("Maybe", lsNamed("Int32")), "Maybe::Present", []LawSpecValue{
				n,
			}, lawspecMachineBits, symbols)
		})
	}
}

var lawspecAdminANewTopicHasThePartitionsAskedForInputs = []string{"(text)", "(int Int32 1 64)"}

func lawspecAdminANewTopicHasThePartitionsAskedForCase(values []LawSpecValue) (float64, bool) {
	symbols := map[string]*lawSpecSymbol{}
	t_ := lsConvert("Text", values[0], lawspecMachineBits)
	n := lsConvert("Int32", values[1], lawspecMachineBits)
	if !(lsTruth(lawSpecEvaluateLawtwinKafkaModelValidTopicName(symbols, t_)) && lsTruth(lsBool(lsTruth(lsBinary(">=", n, lsInteger("Integer", "1"))) && lsTruth(lsBinary("<=", n, lsInteger("Integer", "64")))))) {
		return 0, false
	}
	withCluster := lawspecConnectCluster(symbols, lsConvert("Unit", lsAbsent("Unit"), lawspecMachineBits))
	defer func() {
		_ = lawspecDisconnectCluster(symbols, withCluster)
	}()
	lsInstallHandlers(symbols, map[string]any{"lawtwin.kafka::ability::Admin": NewAdminHandler(lsHandleCodec[any](_lawspecSchema, lawspecMachineBits, "lawtwin.kafka::type::Cluster", symbols).toNative(withCluster))})
	lawspecCheckAdminANewTopicHasThePartitionsAskedFor(symbols, "lawtwin.kafka::Admin: |a new topic has the partitions asked for| [native] search", t_, n, withCluster)
	return 0, true
}

