// Producer: |records sent to one partition are read in the order sent| [reference] —
// ../src/contract.lawspec:1142
// Within one partition, records are stored and read in the order they
// were sent: the later send gets the next offset, and a consumer reading
// from the first gets both, first to last.
// for all (t :: Text) (first :: lawtwin.kafka.model::type::Record) (second ::
// lawtwin.kafka.model::type::Record) => created t 1 implies let a = send (let _lawspecRecordField0
// = t in let _lawspecRecordField1 = lawtwin.kafka::type::PartitionChoice::ToPartition(0) in let
// _lawspecRecordField2 = first in
// lawtwin.kafka::type::ProducerRecord::ProducerRecord(_lawspecRecordField0, _lawspecRecordField1,
// _lawspecRecordField2)) in let b = send (let _lawspecRecordField0 = t in let _lawspecRecordField1
// = lawtwin.kafka::type::PartitionChoice::ToPartition(0) in let _lawspecRecordField2 = second in
// lawtwin.kafka::type::ProducerRecord::ProducerRecord(_lawspecRecordField0, _lawspecRecordField1,
