	lsInstallHandlers(symbols, map[string]any{"lawtwin.kafka::ability::Transactions": NewKafkaTransactions(symbols), "lawtwin.kafka::ability::Broker": sharedCluster, "lawtwin.kafka::ability::Partitioner": NewMurmurPartitioner(symbols)})
